<script lang="ts">
 import { onMount } from 'svelte'; import { request, uploadFile } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Person={id:string;full_name:string}; type Message={id:string;body:string;created_at:string;author_name:string;file_id:string|null}; type Thread={id:string;title:string;kind:string;members:Person[];messages:Message[]};
 let threads=$state<Thread[]>([]),people=$state<Person[]>([]),selected=$state(''),title=$state(''),kind=$state('group'),members=$state<string[]>([]),body=$state(''),attachment=$state<File|null>(null),error=$state(''),loading=$state(true),saving=$state(false);
 let active=$derived(threads.find(x=>x.id===selected)??threads[0]);
 async function load(){loading=true;try{const [rooms,users]=await Promise.all([request<Thread[]>('/v1/admin/collaboration'),request<Person[]>('/v1/colleagues')]);threads=rooms;people=users;selected||=(rooms[0]?.id??'');}catch(cause){error=cause instanceof Error?cause.message:'Kolaborasi tidak dapat dimuat.';}finally{loading=false;}}
 async function create(){saving=true;error='';try{await request('/v1/admin/collaboration',{method:'POST',body:JSON.stringify({title,kind,member_ids:members})});title='';members=[];await load();}catch(cause){error=cause instanceof Error?cause.message:'Ruang tidak dapat dibuat.';}finally{saving=false;}}
 async function send(){if(!active)return;saving=true;error='';try{let file_id:string|null=null;const file=attachment;if(file){const data_base64=await new Promise<string>((ok,bad)=>{const reader=new FileReader();reader.onload=()=>ok(String(reader.result));reader.onerror=bad;reader.readAsDataURL(file);});file_id=(await uploadFile({file_name:file.name,content_type:file.type||'application/octet-stream',data_base64})).id;}await request(`/v1/admin/collaboration/${active.id}/messages`,{method:'POST',body:JSON.stringify({body,file_id})});body='';attachment=null;await load();}catch(cause){error=cause instanceof Error?cause.message:'Pesan tidak dapat dikirim.';}finally{saving=false;}}
 onMount(()=>{void load();const timer=setInterval(()=>void load(),15000);return()=>clearInterval(timer);});
</script>
<main class="workspace-page"><PageHeader title="Collaboration" description="Percakapan kerja, anggota, dan lampiran dalam ruang tenant yang sama." backHref="/admin/dashboard"/>{#if error}<p class="alert">{error}</p>{/if}<section class="layout"><aside class="panel"><form novalidate onsubmit={(e)=>{e.preventDefault();void create();}}><h2>Ruang baru</h2><input bind:value={title} placeholder="Nama ruang" required/><select bind:value={kind}><option value="group">Tim</option><option value="project">Proyek</option><option value="personal">Pribadi</option></select><label>Anggota<select multiple bind:value={members}>{#each people as person}<option value={person.id}>{person.full_name}</option>{/each}</select></label><button disabled={saving}>Buat ruang</button></form><nav>{#each threads as thread (thread.id)}<button class:chosen={active?.id===thread.id} onclick={()=>selected=thread.id}><strong>{thread.title}</strong><small>{thread.members.length} anggota</small></button>{/each}</nav></aside><section class="panel conversation">{#if active}<header><div><h2>{active.title}</h2><p>{active.members.map(x=>x.full_name).join(', ')}</p></div><RefreshButton onclick={load} label="Muat ulang"/></header><div class="messages">{#each active.messages as message (message.id)}<article><strong>{message.author_name}</strong><p>{message.body}</p>{#if message.file_id}<small>Lampiran tersimpan di Berkas</small>{/if}<small>{new Date(message.created_at).toLocaleString('id-ID')}</small></article>{:else}<p class="muted">Belum ada pesan.</p>{/each}</div><form novalidate onsubmit={(e)=>{e.preventDefault();void send();}}><textarea bind:value={body} placeholder="Tulis pesan" required></textarea><input type="file" onchange={(e)=>attachment=e.currentTarget.files?.[0]??null}/><button disabled={saving}>Kirim</button></form>{/if}</section></section></main>
<style>.workspace-page,.layout{display:grid;gap:12px}.layout{grid-template-columns:300px 1fr}.panel{padding:16px;border-radius:var(--radius)}form,nav,.messages{display:grid;gap:8px}nav{margin-top:14px}nav button{text-align:left}h2{font-size:15px}small,p{display:block;color:var(--muted);font-size:12px}.chosen{border-color:var(--accent)}.messages{min-height:260px;align-content:start}.messages article{padding:10px;border:1px solid var(--line);border-radius:var(--radius-sm)}textarea{min-height:70px}.alert{color:var(--danger)}@media(max-width:720px){.layout{grid-template-columns:1fr}}</style>
